// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.sparql;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.List;

import org.junit.jupiter.api.Test;

class SPARQLDataBlockPartsTest {

	@Test
	void preservesTheFirstIriOrFixedReferenceInTheRawBody() {
		String prologue = "BASE <urn:base:>\r\nPREFIX ex: <urn:example:>\r\n";
		List<String> bodies = List.of(
				"<urn:subject> ex:p <urn:object> .",
				"<_:fixed> ex:p <urn:object> .");

		for (String body : bodies) {
			String source = prologue + body;
			SPARQLQueries.DataBlockParts parts = SPARQLQueries.splitDataBlock(source);

			assertEquals(prologue, parts.prologue());
			assertEquals(body, parts.body());
			assertEquals(source, parts.prologue() + parts.body());
		}
	}

	@Test
	void preservesCommentsCrLfAndEscapedUcharSpelling() {
		String prologue = "PREFIX ex: <urn:example:>\r\n";
		String body = "# body comment\r\n<urn:s> ex:p \"\\u0024\" .\r\n";
		String source = prologue + body;

		SPARQLQueries.DataBlockParts parts = SPARQLQueries.splitDataBlock(source);

		assertEquals(prologue, parts.prologue());
		assertEquals(body, parts.body());
		assertEquals(source, parts.prologue() + parts.body());
	}

	@Test
	void keepsEmptyAndCommentOnlyInputsEntirelyInTheirRawBody() {
		for (String source : List.of("", "# only a comment\r\n", "  # comment with leading space\n")) {
			SPARQLQueries.DataBlockParts parts = SPARQLQueries.splitDataBlock(source);

			assertEquals("", parts.prologue());
			assertEquals(source, parts.body());
			assertEquals(source, parts.prologue() + parts.body());
		}
	}

	@Test
	void stopsLeadingStandardHeadersBeforeTurtleDirectives() {
		String prologue = "PREFIX standard: <urn:standard:>\r\n";
		String body = "@prefix turtle: <urn:turtle:> .\r\nturtle:s turtle:p turtle:o .";
		String source = prologue + body;

		SPARQLQueries.DataBlockParts parts = SPARQLQueries.splitDataBlock(source);

		assertEquals(prologue, parts.prologue());
		assertEquals(body, parts.body());
		assertEquals(source, parts.prologue() + parts.body());
	}
}
